"use client"

import * as React from "react"
import { cn } from "cn"

// NOTE: Update these paths if needed
import "../tokens.css"
import "./gradient-text.css"

const gradientNames = [
  "aurora",
  "sunrise",
  "sunset",
  "ocean",
  "forest",
  "fire",
  "candy",
  "lavender",
  "mint",
  "peach",
  "midnight",
  "gold",
  "rainbow",
  "cyber",
  "plasma",
  "mono",
] as const

type GradientName = (typeof gradientNames)[number]

type GradientTextProps = Omit<React.ComponentProps<"span">, "children"> & {
  children?: React.ReactNode
  /** The color set. Defaults to `sunrise`. */
  gradient?: GradientName
  /** How fast the gradient flows. */
  speed?: "slow" | "default" | "fast"
  /** Set to `false` for a static gradient. */
  animated?: boolean
  /** Flow the gradient the other way. */
  reverse?: boolean
  /** Adds a glow. `true` is the default strength. */
  neon?: boolean | "soft" | "default" | "strong"
  /** Flickers the glow like a failing neon tube. */
  flicker?: boolean
  /** Replaces the rendered element, such as a heading. */
  render?: React.ReactElement
}

function GradientText({
  gradient = "sunrise",
  speed = "default",
  animated = true,
  reverse = false,
  neon = false,
  flicker = false,
  className,
  render,
  ...props
}: GradientTextProps) {
  const merged = {
    "data-slot": "gradient-text",
    "data-gradient": gradient === "sunrise" ? undefined : gradient,
    "data-speed": speed === "default" ? undefined : speed,
    "data-animate": animated ? undefined : "false",
    "data-direction": reverse ? "reverse" : undefined,
    "data-neon": neon === true ? "default" : neon || undefined,
    "data-flicker": flicker ? "" : undefined,
    ...props,
    className: cn("np-gradient-text", className),
  }

  if (React.isValidElement(render)) {
    const own = render.props as { className?: string }
    return React.cloneElement(render, {
      ...merged,
      ...(render.props as Record<string, unknown>),
      className: cn(merged.className, own.className),
    } as Record<string, unknown>)
  }

  return <span {...merged} />
}

export { GradientText, gradientNames }
export type { GradientName, GradientTextProps }

/* nepui — Gradient Text */

:is(.np-gradient-text, [data-np-gradient-text]) {
  --np-gradient-text-1: oklch(0.7 0.19 295);
  --np-gradient-text-2: oklch(0.72 0.2 320);
  --np-gradient-text-3: oklch(0.72 0.21 350);
  --np-gradient-text-4: oklch(0.76 0.19 30);
  --np-gradient-text-5: oklch(0.8 0.16 70);
  --np-gradient-text-angle: 90deg;
  --np-gradient-text-duration: 6s;
  --np-gradient-text-ease: linear;
  --np-gradient-text-glow: color-mix(
    in oklab,
    var(--np-gradient-text-3) 85%,
    transparent
  );

  width: fit-content;
  max-width: 100%;
  background-image: linear-gradient(
    var(--np-gradient-text-angle),
    var(--np-gradient-text-1),
    var(--np-gradient-text-2),
    var(--np-gradient-text-3),
    var(--np-gradient-text-4),
    var(--np-gradient-text-5),
    var(--np-gradient-text-1)
  );
  background-size: 200% 100%;
  background-position: 0% 50%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  animation: np-gradient-text-flow var(--np-gradient-text-duration)
    var(--np-gradient-text-ease) infinite;
}

